window.DE_CHUNKS=window.DE_CHUNKS||[];window.DE_CHUNKS.push([{"id":470,"unit":5,"q":"Implement a combinational circuit of half adder using AOI gate.","k":"","s":["Half-adder: Sum=A⊕B, Carry=AB.","Truth table (A,B → S,C): 00→00, 01→10, 10→10, 11→01."]},{"id":471,"unit":5,"q":"Implement a combinational circuit of half adder using NAND logic gates.","k":"","s":["Half-adder: Sum=A⊕B, Carry=AB.","Truth table (A,B → S,C): 00→00, 01→10, 10→10, 11→01."]},{"id":472,"unit":5,"q":"Implement a combinational circuit of half adder using NOR logic gates.","k":"","s":["Half-adder: Sum=A⊕B, Carry=AB.","Truth table (A,B → S,C): 00→00, 01→10, 10→10, 11→01."]},{"id":473,"unit":5,"q":"Implement a combinational circuit of full adder using only 2- input NAND logic gates.","k":"","s":["For inputs A, B and Cin: S=A⊕B⊕Cin.","Carry: Cout=AB+ACin+BCin = AB+Cin(A⊕B).","Use the 8-row truth table and implement these two equations."]},{"id":474,"unit":5,"q":"Implement a combinational circuit of full adder using only 2- input NOR logic gates.","k":"","s":["For inputs A, B and Cin: S=A⊕B⊕Cin.","Carry: Cout=AB+ACin+BCin = AB+Cin(A⊕B).","Use the 8-row truth table and implement these two equations."]},{"id":475,"unit":5,"q":"Implement a combinational circuit of full adder using AOI gates.","k":"","s":["For inputs A, B and Cin: S=A⊕B⊕Cin.","Carry: Cout=AB+ACin+BCin = AB+Cin(A⊕B).","Use the 8-row truth table and implement these two equations."]},{"id":476,"unit":5,"q":"Implement a combinational circuit of half subtractor using AOI gates.","k":"","s":["Half-subtractor: Difference=A⊕B, Borrow=A'B.","Truth table (A,B → D,Borrow): 00→00, 01→11, 10→10, 11→00."]},{"id":477,"unit":5,"q":"Implement a combinational circuit of half subtractor using NAND logic gates.","k":"","s":["Half-subtractor: Difference=A⊕B, Borrow=A'B.","Truth table (A,B → D,Borrow): 00→00, 01→11, 10→10, 11→00."]},{"id":478,"unit":5,"q":"Implement a combinational circuit of half subtractor using NOR logic gates.","k":"","s":["Half-subtractor: Difference=A⊕B, Borrow=A'B.","Truth table (A,B → D,Borrow): 00→00, 01→11, 10→10, 11→00."]},{"id":479,"unit":5,"q":"Implement a combinational circuit of full subtractor using only 2- input NAND logic gates.","k":"","s":["Difference: D=A⊕B⊕Bin.","Borrow: Bout=A'B + A'Bin + B·Bin.","These equations come directly from the 8-row full-subtractor truth table."]},{"id":480,"unit":5,"q":"Implement a combinational circuit of full subtractor using only 2- input NOR logic gates.","k":"","s":["Difference: D=A⊕B⊕Bin.","Borrow: Bout=A'B + A'Bin + B·Bin.","These equations come directly from the 8-row full-subtractor truth table."]},{"id":481,"unit":5,"q":"Implement a combinational circuit of full subtractor using AOI gates.","k":"","s":["Difference: D=A⊕B⊕Bin.","Borrow: Bout=A'B + A'Bin + B·Bin.","These equations come directly from the 8-row full-subtractor truth table."]},{"id":482,"unit":5,"q":"Show how a full-adder can be converted to a full-subtractor with the addition of inverter circuit.","k":"","s":["Difference: D=A⊕B⊕Bin.","Borrow: Bout=A'B + A'Bin + B·Bin.","These equations come directly from the 8-row full-subtractor truth table."]},{"id":483,"unit":5,"q":"With logic circuit describe the function of: Full adder,write the simplified Boolean functions for its outputs.","k":"","s":["For inputs A, B and Cin: S=A⊕B⊕Cin.","Carry: Cout=AB+ACin+BCin = AB+Cin(A⊕B).","Use the 8-row truth table and implement these two equations."]},{"id":484,"unit":5,"q":"Design the truth table of full adder and write the simplified Boolean function for its outputs.","k":"","s":["For inputs A, B and Cin: S=A⊕B⊕Cin.","Carry: Cout=AB+ACin+BCin = AB+Cin(A⊕B).","Use the 8-row truth table and implement these two equations."]},{"id":485,"unit":5,"q":"Design a full adder circuit using two half adders and gates.","k":"","s":["Half adder 1: S1=A⊕B, C1=AB.","Half adder 2: S=S1⊕Cin, C2=S1·Cin.","Cout=C1+C2=AB+Cin(A⊕B).","Thus two half adders and one OR gate form a full adder."]},{"id":486,"unit":5,"q":"Differentiate between serial and parallel adders.","k":"","s":["Identify the required Boolean relation or circuit from the question.","Apply the relevant truth table, Boolean theorem, K-map or combinational-circuit equation.","Write the simplified final result and include the requested logic diagram when needed."]}]);